SELECT r.id, r.conversation_id, r.turn_id, r.message_id, r.queue_seq, r.status, r.created_at, r.updated_at FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.conversation_id, data_rows.turn_id, data_rows.message_id, data_rows.queue_seq, data_rows.status, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `id`, `conversation_id`, `turn_id`, `message_id`, `queue_seq`, `status`, `created_at`, `updated_at` FROM turn_queue)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)